package codegen

// messageTmpl 定义每个消息生成的 Go 文件。
const messageTmpl = `{{define "message"}}
// Code generated by schemagen; DO NOT EDIT.

package {{.Pkg}}

import (
	"fmt"

	{{printf "%q" "github.com/lisama569/schema-wire-sdk-go/wire"}}
)

// {{export .Msg.Name}} 是 schema 消息 "{{.Msg.Name}}" 的生成类型，
// 合并了该消息在全部版本中出现过的字段。指针为 nil 表示该字段未出现。
type {{export .Msg.Name}} struct {
{{- range .Msg.Fields}}
	// field #{{.Number}}: active since v{{.Since}}{{if .Until}} until v{{.Until}}{{end}}
	{{fieldVar .}} *{{goType .}}
{{- end}}

	// unknown 保存未被本代码识别（新版本新增或已移除编号）的原始字段记录，
	// 重新编码时原样透传。
	unknown []wire.RawRecord
}

// UnknownFieldNumbers 返回未识别字段的编号（去重，供测试/诊断）。
func (m *{{export .Msg.Name}}) UnknownFieldNumbers() []uint32 {
	if m == nil {
		return nil
	}
	seen := map[uint32]struct{}{}
	out := make([]uint32, 0, len(m.unknown))
	for _, rec := range m.unknown {
		if _, ok := seen[rec.Num]; !ok {
			seen[rec.Num] = struct{}{}
			out = append(out, rec.Num)
		}
	}
	return out
}

// knownNumberAt{{export .Msg.Name}} 报告编号 n 在版本 v 是否对应一个已知字段身份。
func knownNumberAt{{export .Msg.Name}}(n uint32, v uint32) bool {
	switch n {
{{- range $g := fieldGroups .Msg}}
	case {{index $g 0 | num}}:
		{{range $i, $f := $g}}{{if $i}} else {{end}}{{rangeIf $f "v"}} { return true }{{end}}
		return false
{{end}}	}
	return false
}

// encodeBody{{export .Msg.Name}} 以 viewVersion 序列化消息体（不含信封）。
// 目标版本下有活跃身份的编号由显式字段写出；只有“目标版本中不对应任何
// 已知字段”的原始记录才透传，避免同一编号被写两次。
func encodeBody{{export .Msg.Name}}(m *{{export .Msg.Name}}, viewVersion uint32) ([]byte, error) {
	var b []byte
{{- range .Msg.Fields}}
	if m.{{fieldVar .}} != nil {
		b = wire.AppendTag(b, {{.Number}}, {{wireType .}})
		{{encodeStmt .}}
	}
{{- end}}
	// 仅透传“目标版本下没有已知活跃身份”的原始记录。
	for _, rec := range m.unknown {
		if !knownNumberAt{{export .Msg.Name}}(rec.Num, viewVersion) {
			b = rec.AppendTo(b)
		}
	}
	return b, nil
}

// decodeBody{{export .Msg.Name}} 解析消息体。
// wireVersion = 报文自报版本，决定同编号字段的身份（写入方视角）；
// knownVersion = 本地代码理解到的版本，该版本不可见的字段一律作为未知保留。
func decodeBody{{export .Msg.Name}}(p []byte, tgt *{{export .Msg.Name}}, wireVersion, knownVersion uint32) error {
	r := wire.NewReader(p)
	for !r.EOF() {
		// 先完整读取一条原始记录（含 tag），再决定按已知字段解析还是原样保留。
		// 这样已知/未知路径的游标推进完全一致，不会重复消费。
		start := r.Pos()
		rec := r.ReadRawRecord()
		if err := r.Err(); err != nil {
			return err
		}
		num, wt := rec.Num, rec.WT
		handled := false
		switch num {
{{- range $g := fieldGroups .Msg}}
		case {{index $g 0 | num}}:
			// 身份选择：优先按报文自报版本（写入方语义）；
			// 若该版本下编号无任何身份（字段来自更高版本，经老代码透传），
			// 再按本地理解版本解释——使新代码能还原透传过来的新字段。
			identity := -1
			{{range $i, $f := $g}}{{if $i}} else {{end}}{{wvIf $f}} { identity = {{$i}} }{{end}}
			if identity == -1 {
				{{range $i, $f := $g}}{{if $i}} else {{end}}{{kvIf $f}} { identity = {{$i}} }{{end}}
			}
			switch identity {
			{{- range $i, $f := $g}}
			case {{$i}}:
				if {{visibleIf $f}} {
					if wt != {{wireType $f}} {
						return &wire.Error{Kind: wire.KindCorrupt,
							Detail: fmt.Sprintf("field %d: unexpected wire type %d", num, wt)}
					}
					if err := decodeField{{export $.Msg.Name}}_{{fieldVar $f}}(rec.Raw, tgt, wireVersion, knownVersion); err != nil {
						return err
					}
					handled = true
				}
			{{- end}}
			}
	{{end}}
		}
		if handled {
			continue
		}
		// 未知字段 / 当前视图版本不可见字段：原样保留记录字节。
		_ = start
		tgt.unknown = append(tgt.unknown, rec)
	}
	return nil
}

{{- range .Msg.Fields}}
// decodeField{{export $.Msg.Name}}_{{fieldVar .}} 在“单条字段记录”的原始字节上
// 跳过 tag 后解析字段 #{{.Number}} ({{.Name}}) 的值。
func decodeField{{export $.Msg.Name}}_{{fieldVar .}}(rec []byte, tgt *{{export $.Msg.Name}}, wireVersion, knownVersion uint32) error {
	r := wire.NewReader(rec)
	if _, _ = r.ReadTag(); r.Err() != nil {
		return r.Err()
	}
	{{decodeStmt .}}
	return r.Err()
}
{{end}}
// Marshal{{export .Msg.Name}} 以指定视图版本把消息写入含信封的完整报文。
func Marshal{{export .Msg.Name}}(m *{{export .Msg.Name}}, viewVersion uint32) ([]byte, error) {
	if viewVersion == 0 {
		return nil, &wire.Error{Kind: wire.KindIncompatibleVersion,
			Detail: "view version must be >= 1"}
	}
	body, err := encodeBody{{export .Msg.Name}}(m, viewVersion)
	if err != nil {
		return nil, err
	}
	return wire.EncodeMessage(viewVersion, body), nil
}

// Unmarshal{{export .Msg.Name}} 从含信封的完整报文解码到 m。
//
//   - knownVersion：本地代码“理解到”的 schema 版本（模拟老二进制时传其发布
//     版本；传 schemaMaxVersion 表示当前最新代码）。编号在该版本不可见的字段
//     一律作为未知原始记录保留。
//   - strict：为 true 时，报文版本高于 knownVersion 直接判为版本不兼容；
//     为 false 时前向兼容——新字段保留、旧字段照常解码。
func Unmarshal{{export .Msg.Name}}(b []byte, m *{{export .Msg.Name}}, knownVersion uint32, strict bool) (envelopeVersion uint32, err error) {
	version, body, err := wire.DecodeEnvelope(b)
	if err != nil {
		return 0, err
	}
	if knownVersion == 0 {
		knownVersion = SchemaMaxVersion
	}
	if err := requireReadable(version, knownVersion, strict); err != nil {
		return 0, err
	}
	if err := decodeBody{{export .Msg.Name}}(body, m, version, knownVersion); err != nil {
		return 0, err
	}
	return version, nil
}
{{end}}
`
